/bin/zsh -lc "ls -la && shasum -a 256 ledger.json && python3 -c 'import json; d=json.load(open(\"ledger.json\")); seen=set(); refund=0; print(\"orders\",sum(x[\"paid_won\"] for x in d[\"orders\"]));
for x in d[\"refund_deliveries\"]:
 if x[\"event_id\"] not in seen: seen.add(x[\"event_id\"]); refund+=x[\"refund_won\"]
print(\"unique_refunds\",refund); print(\"contract_net\",sum(x[\"paid_won\"] for x in d[\"orders\"])-refund); print(\"raw_delivery_net\",sum(x[\"paid_won\"] for x in d[\"orders\"])-sum(x[\"refund_won\"] for x in d[\"refund_deliveries\"]))'"

